function Animal(name) { this.name = name; }
Animal.prototype.type = 'animal';
const cat = new Animal('Whiskers');
for (const key in cat) {
  if (cat.hasOwnProperty(key)) {
    console.log(key + ': ' + cat[key]);
  }
}
